total_count\":0,\"+1\":0,\"-1\":0,\"laugh\":0,\"hooray\":0,\"confused\":0,\"heart\":0,\"rocket\":0,\"eyes\":0},\"timeline_url\":\"ghrepos/hypertidy/ncmeta/issues/46/timeline\",\"performed_via_github_app\":null,\"state_reason\":null},{\"url\":\"ghrepos/hypertidy/ncmeta/issues/45\",\"repository_url\":\"ghrepos/hypertidy/ncmeta\",\"labels_url\":\"ghrepos/hypertidy/ncmeta/issues/45/labels{/name}\",\"comments_url\":\"ghrepos/hypertidy/ncmeta/issues/45/comments\",\"events_url\":\"ghrepos/hypertidy/ncmeta/issues/45/events\",\"html_url\":\"https://github.com/hypertidy/ncmeta/pull/45\",\"id\":1338151138,\"node_id\":\"PR_kwDOBZkC0M49I3wb\",\"number\":45,\"title\":\"nc_var: only keep items from RNetCDF::var.inq.nc that fit in a tibble row\",\"user\":{\"login\":\"mjwoods\",\"id\":16091567,\"node_id\":\"MDQ6VXNlcjE2MDkxNTY3\",\"avatar_url\":\"https://avatars.githubusercontent.com/u/16091567?v=4\",\"gravatar_id\":\"\",\"url\":\"https://api.github.com/users/mjwoods\",\"html_url\":\"https://github.com/mjwoods\",\"followers_url\":\"https://api.github.com/users/mjwoods/followers\",\"following_url\":\"https://api.github.com/users/mjwoods/following{/other_user}\",\"gists_url\":\"https://api.github.com/users/mjwoods/gists{/gist_id}\",\"starred_url\":\"https://api.github.com/users/mjwoods/starred{/owner}{/repo}\",\"subscriptions_url\":\"https://api.github.com/users/mjwoods/subscriptions\",\"organizations_url\":\"https://api.github.com/users/mjwoods/orgs\",\"repos_url\":\"https://api.github.com/users/mjwoods/repos\",\"events_url\":\"https://api.github.com/users/mjwoods/events{/privacy}\",\"received_events_url\":\"https://api.github.com/users/mjwoods/received_events\",\"type\":\"User\",\"user_view_type\":\"public\",\"site_admin\":false},\"labels\":[],\"state\":\"closed\",\"locked\":false,\"assignees\":[],\"milestone\":null,\"comments\":0,\"created_at\":\"2022-08-14T06:41:42Z\",\"updated_at\":\"2022-08-14T07:43:18Z\",\"closed_at\":\"2022-08-14T07:43:18Z\",\"assignee\":null,\"author_association\":\"CONTRIBUTOR\",\"issue_field_values\":[],\"type\":null,\"active_lock_reason\":null,\"draft\":false,\"pull_request\":{\"url\":\"ghrepos/hypertidy/ncmeta/pulls/45\",\"html_url\":\"https://github.com/hypertidy/ncmeta/pull/45\",\"diff_url\":\"https://github.com/hypertidy/ncmeta/pull/45.diff\",\"patch_url\":\"https://github.com/hypertidy/ncmeta/pull/45.patch\",\"merged_at\":\"2022-08-14T07:43:18Z\"},\"body\":\"Although the solution in #44 works for now, it would break if new vector items were added to the output of RNetCDF::var.inq.nc. This could occur if RNetCDF is extended to support new features in the NetCDF library. The changes in this PR should ensure that nc_var continues to work, by excluding unknown vector items that are returned by `var.inq.nc`.\",\"closed_by\":{\"login\":\"mdsumner\",\"id\":4107631,\"node_id\":\"MDQ6VXNlcjQxMDc2MzE=\",\"avatar_url\":\"https://avatars.githubusercontent.com/u/4107631?v=4\",\"gravatar_id\":\"\",\"url\":\"https://api.github.com/users/mdsumner\",\"html_url\":\"https://github.com/mdsumner\",\"followers_url\":\"https://api.github.com/users/mdsumner/followers\",\"following_url\":\"https://api.github.com/users/mdsumner/following{/other_user}\",\"gists_url\":\"https://api.github.com/users/mdsumner/gists{/gist_id}\",\"starred_url\":\"https://api.github.com/users/mdsumner/starred{/owner}{/repo}\",\"subscriptions_url\":\"https://api.github.com/users/mdsumner/subscriptions\",\"organizations_url\":\"https://api.github.com/users/mdsumner/orgs\",\"repos_url\":\"https://api.github.com/users/mdsumner/repos\",\"events_url\":\"https://api.github.com/users/mdsumner/events{/privacy}\",\"received_events_url\":\"https://api.github.com/users/mdsumner/received_events\",\"type\":\"User\",\"user_view_type\":\"public\",\"site_admin\":false},\"reactions\":{\"url\":\"ghrepos/hypertidy/ncmeta/issues/45/reactions\",\"total_count\":0,\"+1\":0,\"-1\":0,\"laugh\":0,\"hooray\":0,\"confused\":0,\"heart\":0,\"rocket\":0,\"eyes\":0},\"timeline_url\":\"ghrepos/hypertidy/ncmeta/issues/45/timeline\",\"performed_via_github_app\":null,\"state_reason\":null},{\"url\":\"ghrepos/hypertidy/ncmeta/issues/44\",\"repository_url\":\"ghrepos/hypertidy/ncmeta\",\"labels_url\":\"ghrepos/hypertidy/ncmeta/issues/44/labels{/name}\",\"comments_url\":\"ghrepos/hypertidy/ncmeta/issues/44/comments\",\"events_url\":\"ghrepos/hypertidy/ncmeta/issues/44/events\",\"html_url\":\"https://github.com/hypertidy/ncmeta/pull/44\",\"id\":1337877712,\"node_id\":\"PR_kwDOBZkC0M49IFFC\",\"number\":44,\"title\":\"Handle vectors of different lengths from RNetCDF::var.inq.nc\",\"user\":{\"login\":\"mjwoods\",\"id\":16091567,\"node_id\":\"MDQ6VXNlcjE2MDkxNTY3\",\"avatar_url\":\"https://avatars.githubusercontent.com/u/16091567?v=4\",\"gravatar_id\":\"\",\"url\":\"https://api.github.com/users/mjwoods\",\"html_url\":\"https://github.com/mjwoods\",\"followers_url\":\"https://api.github.com/users/mjwoods/followers\",\"following_url\":\"https://api.github.com/users/mjwoods/following{/other_user}\",\"gists_url\":\"https://api.github.com/users/mjwoods/gists{/gist_id}\",\"starred_url\":\"https://api.github.com/users/mjwoods/starred{/owner}{/repo}\",\"subscriptions_url\":\"https://api.github.com/users/mjwoods/subscriptions\",\"organizations_url\":\"https://api.github.com/users/mjwoods/orgs\",\"repos_url\":\"https://api.github.com/users/mjwoods/repos\",\"events_url\":\"https://api.github.com/users/mjwoods/events{/privacy}\",\"received_events_url\":\"https://api.github.com/users/mjwoods/received_events\",\"type\":\"User\",\"user_view_type\":\"public\",\"site_admin\":false},\"labels\":[],\"state\":\"closed\",\"locked\":false,\"assignees\":[],\"milestone\":null,\"comments\":3,\"created_at\":\"2022-08-13T06:46:20Z\",\"updated_at\":\"2022-08-13T07:36:33Z\",\"closed_at\":\"2022-08-13T07:36:33Z\",\"assignee\":null,\"author_association\":\"CONTRIBUTOR\",\"issue_field_values\":[],\"type\":null,\"active_lock_reason\":null,\"draft\":false,\"pull_request\":{\"url\":\"ghrepos/hypertidy/ncmeta/pulls/44\",\"html_url\":\"https://github.com/hypertidy/ncmeta/pull/44\",\"diff_url\":\"https://github.com/hypertidy/ncmeta/pull/44.diff\",\"patch_url\":\"https://github.com/hypertidy/ncmeta/pull/44.patch\",\"merged_at\":\"2022-08-13T07:36:33Z\"},\"body\":\"Fixes https://github.com/hypertidy/ncmeta/issues/42\\r\\n\\r\\n`RNetCDF::var.inq.nc` returns additional elements when the file format is `netcdf4`. Some of these elements are vectors, with lengths that may differ from the number of dimensions in a variable. For example, `chunksizes` either has one element per dimension, or it is NULL for contiguous storage. Also, recent NetCDF library versions provide a filter API that can apply multiple filters to each variable, and descriptions of the filters are returned in vectors `filter_id` and `filter_params`, whose lengths are unrelated to the variable's dimensions.\\r\\n\\r\\nTo handle vectors of different lengths in the output from `nc_var`, vector elements are stored as list columns within the tibble produced by `nc_var`.\\r\\n\\r\\nAlso, the tibble produced within `nc_axes` does not require all elements from `RNetCDF::var.inq.nc`, so selecting only those required avoids the problem of differing vector lengths.\",\"closed_by\":{\"login\":\"mdsumner\",\"id\":4107631,\"node_id\":\"MDQ6VXNlcjQxMDc2MzE=\",\"avatar_url\":\"https://avatars.githubusercontent.com/u/4107631?v=4\",\"gravatar_id\":\"\",\"url\":\"https://api.github.com/users/mdsumner\",\"html_url\":\"https://github.com/mdsumner\",\"followers_url\":\"https://api.github.com/users/mdsumner/followers\",\"following_url\":\"https://api.github.com/users/mdsumner/following{/other_user}\",\"gists_url\":\"https://api.github.com/users/mdsumner/gists{/gist_id}\",\"starred_url\":\"https://api.github.com/users/mdsumner/starred{/owner}{/repo}\",\"subscriptions_url\":\"https://api.github.com/users/mdsumner/subscriptions\",\"organizations_url\":\"https://api.github.com/users/mdsumner/orgs\",\"repos_url\":\"https://api.github.com/users/mdsumner/repos\",\"events_url\":\"https://api.github.com/users/mdsumner/events{/privacy}\",\"received_events_url\":\"https://api.github.com/users/mdsumner/received_events\",\"type\":\"User\",\"user_view_type\":\"public\",\"site_admin\":false},\"reactions\":{\"url\":\"ghrepos/hypertidy/ncmeta/issues/44/reactions\",\"total_count\":0,\"+1\":0,\"-1\":0,\"laugh\":0,\"hooray\":0,\"confused\":0,\"heart\":0,\"rocket\":0,\"eyes\":0},\"timeline_url\":\"ghrepos/hypertidy/ncmeta/issues/44/timeline\",\"performed_via_github_app\":null,\"state_reason\":null},{\"url\":\"ghrepos/hypertidy/ncmeta/issues/43\",\"repository_url\":\"ghrepos/hypertidy/ncmeta\",\"labels_url\":\"ghrepos/hypertidy/ncmeta/issues/43/labels{/name}\",\"comments_url\":\"ghrepos/hypertidy/ncmeta/issues/43/comments\",\"events_url\":\"ghrepos/hypertidy/ncmeta/issues/43/events\",\"html_url\":\"https://github.com/hypertidy/ncmeta/pull/43\",\"id\":1317587797,\"node_id\":\"PR_kwDOBZkC0M48FDhd\",\"number\":43,\"title\":\"Fix nested variable info\",\"user\":{\"login\":\"mdsumner\",\"id\":4107631,\"node_id\":\"MDQ6VXNlcjQxMDc2MzE=\",\"avatar_url\":\"https://avatars.githubusercontent.com/u/4107631?v=4\",\"gravatar_id\":\"\",\"url\":\"https://api.github.com/users/mdsumner\",\"html_url\":\"https://github.com/mdsumner\",\"followers_url\":\"https://api.github.com/users/mdsumner/followers\",\"following_url\":\"https://api.github.com/users/mdsumner/following{/other_user}\",\"gists_url\":\"https://api.github.com/users/mdsumner/gists{/gist_id}\",\"starred_url\":\"https://api.github.com/users/mdsumner/starred{/owner}{/repo}\",\"subscriptions_url\":\"https://api.github.com/users/mdsumner/subscriptions\",\"organizations_url\":\"https://api.github.com/users/mdsumner/orgs\",\"repos_url\":\"https://api.github.com/users/mdsumner/repos\",\"events_url\":\"https://api.github.com/users/mdsumner/events{/privacy}\",\"received_events_url\":\"https://api.github.com/users/mdsumner/received_events\",\"type\":\"User\",\"user_view_type\":\"public\",\"site_admin\":false},\"labels\":[],\"state\":\"closed\",\"locked\":false,\"assignees\":[],\"milestone\":null,\"comments\":1,\"created_at\":\"2022-07-26T01:46:45Z\",\"updated_at\":\"2022-08-15T01:10:13Z\",\"closed_at\":\"2022-08-15T01:10:13Z\",\"assignee\":null,\"author_association\":\"MEMBER\",\"issue_field_values\":[],\"type\":null,\"active_lock_reason\":null,\"draft\":false,\"pull_request\":{\"url\":\"ghrepos/hypertidy/ncmeta/pulls/43\",\"html_url\":\"https://github.com/hypertidy/ncmeta/pull/43\",\"diff_url\":\"https://github.com/hypertidy/ncmeta/pull/43.diff\",\"patch_url\":\"https://github.com/hypertidy/ncmeta/pull/43.patch\",\"merged_at\":null},\"body\":\"for #42 this allows var info to have nested elements (dimids and chunksizes) \",\"closed_by\":{\"login\":\"mdsumner\",\"id\":4107631,\"node_id\":\"MDQ6VXNlcjQxMDc2MzE=\",\"avatar_url\":\"https://avatars.githubusercontent.com/u/4107631?v=4\",\"gravatar_id\":\"\",\"url\":\"https://api.github.com/users/mdsumner\",\"html_url\":\"https://github.com/mdsumner\",\"followers_url\":\"https://api.github.com/users/mdsumner/followers\",\"following_url\":\"https://api.github.com/users/mdsumner/following{/other_user}\",\"gists_url\":\"https://api.github.com/users/mdsumner/gists{/gist_id}\",\"starred_url\":\"https://api.github.com/users/mdsumner/starred{/owner}{/repo}\",\"subscriptions_url\":\"https://api.github.com/users/mdsumner/subscriptions\",\"organizations_url\":\"https://api.github.com/users/mdsumner/orgs\",\"repos_url\":\"https://api.github.com/users/mdsumner/repos\",\"events_url\":\"https://api.github.com/users/mdsumner/events{/privacy}\",\"received_events_url\":\"https://api.github.com/users/mdsumner/received_events\",\"type\":\"User\",\"user_view_type\":\"public\",\"site_admin\":false},\"reactions\":{\"url\":\"ghrepos/hypertidy/ncmeta/issues/43/reactions\",\"total_count\":0,\"+1\":0,\"-1\":0,\"laugh\":0,\"hooray\":0,\"confused\":0,\"heart\":0,\"rocket\":0,\"eyes\":0},\"timeline_url\":\"ghrepos/hypertidy/ncmeta/issues/43/timeline\",\"performed_via_github_app\":null,\"state_reason\":null},{\"url\":\"ghrepos/hypertidy/ncmeta/issues/42\",\"repository_url\":\"ghrepos/hypertidy/ncmeta\",\"labels_url\":\"ghrepos/hypertidy/ncmeta/issues/42/labels{/name}\",\"comments_url\":\"ghrepos/hypertidy/ncmeta/issues/42/comments\",\"events_url\":\"ghrepos/hypertidy/ncmeta/issues/42/events\",\"html_url\":\"https://github.com/hypertidy/ncmeta/issues/42\",\"id\":1317437975,\"node_id\":\"I_kwDOBZkC0M5OhoIX\",\"number\":42,\"title\":\"Tibble issue with some NetCDF4 files.\",\"user\":{\"login\":\"dblodgett-usgs\",\"id\":1492803,\"node_id\":\"MDQ6VXNlcjE0OTI4MDM=\",\"avatar_url\":\"https://avatars.githubusercontent.com/u/1492803?v=4\",\"gravatar_id\":\"\",\"url\":\"https://api.github.com/users/dblodgett-usgs\",\"html_url\":\"https://github.com/dblodgett-usgs\",\"followers_url\":\"https://api.github.com/users/dblodgett-usgs/followers\",\"following_url\":\"https://api.github.com/users/dblodgett-usgs/following{/other_user}\",\"gists_url\":\"https://api.github.com/users/dblodgett-usgs/gists{/gist_id}\",\"starred_url\":\"https://api.github.com/users/dblodgett-usgs/starred{/owner}{/repo}\",\"subscriptions_url\":\"https://api.github.com/users/dblodgett-usgs/subscriptions\",\"organizations_url\":\"https://api.github.com/users/dblodgett-usgs/orgs\",\"repos_url\":\"https://api.github.com/users/dblodgett-usgs/repos\",\"events_url\":\"https://api.github.com/users/dblodgett-usgs/events{/privacy}\",\"received_events_url\":\"https://api.github.com/users/dblodgett-usgs/received_events\",\"type\":\"User\",\"user_view_type\":\"public\",\"site_admin\":false},\"labels\":[],\"state\":\"closed\",\"locked\":false,\"assignees\":[],\"milestone\":null,\"comments\":30,\"created_at\":\"2022-07-25T22:15:55Z\",\"updated_at\":\"2022-12-05T16:10:37Z\",\"closed_at\":\"2022-10-27T00:43:47Z\",\"assignee\":null,\"author_association\":\"CONTRIBUTOR\",\"issue_field_values\":[],\"type\":null,\"active_lock_reason\":null,\"sub_issues_summary\":{\"total\":0,\"completed\":0,\"percent_completed\":0},\"issue_dependencies_summary\":{\"blocked_by\":0,\"total_blocked_by\":0,\"blocking\":0,\"total_blocking\":0},\"body\":\"Issue is coming from here. https://github.com/hypertidy/ncmeta/blob/master/R/nc_var.R#L30\\r\\n\\r\\nWhat's your preferred fix here @mdsumner ?\\r\\n\\r\\n``` r\\r\\nf <- file.path(tempdir(), \\\"temp.nc\\\")\\r\\ndownload.file(\\\"http://wrf-se-ak-ar5.s3.amazonaws.com/ccsm/hist/daily/1980/WRFDS_1980-01-01.nc\\\", f, mode = \\\"wb\\\")\\r\\n\\r\\nncmeta::nc_meta(f)\\r\\n#> Error:\\r\\n#> ! Tibble columns must have compatible sizes.\\r\\n#> • Size 2: Columns `filter_id` and `filter_params`.\\r\\n#> • Size 3: Column `chunksizes`.\\r\\n#> ℹ Only values of size one are recycled.\\r\\n\\r\\n# it's because of this\\r\\nnc <- RNetCDF::open.nc(f)\\r\\nvi <- RNetCDF::var.inq.nc(nc, 1)\\r\\n(vi <- vi[lengths(vi) > 1])\\r\\n#> $dimids\\r\\n#> [1] 3 2 0\\r\\n#> \\r\\n#> $chunksizes\\r\\n#> [1] 320 250   1\\r\\n#> \\r\\n#> $filter_id\\r\\n#> [1] 2 1\\r\\n#> \\r\\n#> $filter_params\\r\\n#> $filter_params[[1]]\\r\\n#> [1] 4\\r\\n#> \\r\\n#> $filter_params[[2]]\\r\\n#> [1] 5\\r\\n\\r\\ntibble::as_tibble(vi)\\r\\n#> Error:\\r\\n#> ! Tibble columns must have compatible sizes.\\r\\n#> • Size 2: Columns `filter_id` and `filter_params`.\\r\\n#> • Size 3: Columns `dimids` and `chunksizes`.\\r\\n#> ℹ Only values of size one are recycled.\\r\\n```\\r\\n\\r\\n<sup>Created on 2022-07-25 by the [reprex package](https://reprex.tidyverse.org) (v2.0.1)</sup>\\r\\n\",\"closed_by\":{\"login\":\"mdsumner\",\"id\":4107631,\"node_id\":\"MDQ6VXNlcjQxMDc2MzE=\",\"avatar_url\":\"https://avatars.githubusercontent.com/u/4107631?v=4\",\"gravatar_id\":\"\",\"url\":\"https://api.github.com/users/mdsumner\",\"html_url\":\"https://github.com/mdsumner\",\"followers_url\":\"https://api.github.com/users/mdsumner/followers\",\"following_url\":\"https://api.github.com/users/mdsumner/following{/other_user}\",\"gists_url\":\"https://api.github.com/users/mdsumner/gists{/gist_id}\",\"starred_url\":\"https://api.github.com/users/mdsumner/starred{/owner}{/repo}\",\"subscriptions_url\":\"https://api.github.com/users/mdsumner/subscriptions\",\"organizations_url\":\"https://api.github.com/users/mdsumner/orgs\",\"repos_url\":\"https://api.github.com/users/mdsumner/repos\",\"events_url\":\"https://api.github.com/users/mdsumner/events{/privacy}\",\"received_events_url\":\"https://api.github.com/users/mdsumner/received_events\",\"type\":\"User\",\"user_view_type\":\"public\",\"site_admin\":false},\"reactions\":{\"url\":\"ghrepos/hypertidy/ncmeta/issues/42/reactions\",\"total_count\":0,\"+1\":0,\"-1\":0,\"laugh\":0,\"hooray\":0,\"confused\":0,\"heart\":0,\"rocket\":0,\"eyes\":0},\"timeline_url\":\"ghrepos/hypertidy/ncmeta/issues/42/timeline\",\"performed_via_github_app\":null,\"state_reason\":\"completed\",\"pinned_comment\":null},{\"url\":\"ghrepos/hypertidy/ncmeta/issues/41\",\"repository_url\":\"ghrepos/hypertidy/ncmeta\",\"labels_url\":\"ghrepos/hypertidy/ncmeta/issues/41/labels{/name}\",\"comments_url\":\"ghrepos/hypertidy/ncmeta/issues/41/comments\",\"events_url\":\"ghrepos/hypertidy/ncmeta/issues/41/events\",\"html_url\":\"https://github.com/hypertidy/ncmeta/issues/41\",\"id\":911785142,\"node_id\":\"MDU6SXNzdWU5MTE3ODUxNDI=\",\"number\":41,\"title\":\"Plans to support extended grid mapping attributes (as defined by CF-1.7 and later)?\",\"user\":{\"login\":\"dschlaep\",\"id\":4205019,\"node_id\":\"MDQ6VXNlcjQyMDUwMTk=\",\"avatar_url\":\"https://avatars.githubusercontent.com/u/4205019?v=4\",\"gravatar_id\":\"\",\"url\":\"https://api.github.com/users/dschlaep\",\"html_url\":\"https://github.com/dschlaep\",\"followers_url\":\"https://api.github.com/users/dschlaep/followers\",\"following_url\":\"https://api.github.com/users/dschlaep/following{/other_user}\",\"gists_url\":\"https://api.github.com/users/dschlaep/gists{/gist_id}\",\"starred_url\":\"https://api.github.com/users/dschlaep/starred{/owner}{/repo}\",\"subscriptions_url\":\"https://api.github.com/users/dschlaep/subscriptions\",\"organizations_url\":\"https://api.github.com/users/dschlaep/orgs\",\"repos_url\":\"https://api.github.com/users/dschlaep/repos\",\"events_url\":\"https://api.github.com/users/dschlaep/events{/privacy}\",\"received_events_url\":\"https://api.github.com/users/dschlaep/received_events\",\"type\":\"User\",\"user_view_type\":\"public\",\"site_admin\":false},\"labels\":[],\"state\":\"open\",\"locked\":false,\"assignees\":[],\"milestone\":null,\"comments\":2,\"created_at\":\"2021-06-04T19:38:19Z\",\"updated_at\":\"2021-06-10T12:53:34Z\",\"closed_at\":null,\"assignee\":null,\"author_association\":\"NONE\",\"issue_field_values\":[],\"type\":null,\"active_lock_reason\":null,\"sub_issues_summary\":{\"total\":0,\"completed\":0,\"percent_completed\":0},\"issue_dependencies_summary\":{\"blocked_by\":0,\"total_blocked_by\":0,\"blocking\":0,\"total_blocking\":0},\"body\":\"I would like to ask if you would consider enhancing `ncmeta` so that it would support extended grid mapping attributes as defined by CF-1.7 and later?\\r\\n\\r\\nCF conventions before 1.7 required the grid\\\\_mapping attribute of a variable to be an exact match with the variable name that provided the grid mapping: e.g,\\r\\n\\r\\n    int crs ;\\r\\n      crs:grid_mapping_name = \\\"latitude_longitude\\\" ;\\r\\n    double variable ;\\r\\n      variable:grid_mapping = \\\"crs\\\" ;\\r\\n\\r\\nThis is what package `ncmeta` supports with the current implementation of the function `ncmeta:::nc_grid_mapping_atts.data.frame()`:\\r\\n\\r\\n    grid_mapping_atts <- dplyr::filter(x, variable %in% grid_mapping_vars$value)\\r\\n\\r\\nNewer versions of CF, however, expanded the concept of grid mapping starting with [CF-1.7](http://cfconventions.org/Data/cf-conventions/cf-conventions-1.7/cf-conventions.html#grid-mappings-and-projections) to handle cases with more than one crs:\\r\\n\\r\\n    The attribute takes a string value with two possible formats. In the first format, it is a single word, which names a grid mapping variable. In the second format, it is a blank-separated list of words \\\"grid_mapping_variable: coordinate_variable [coordinate_variable ...] [grid_mapping_variable: ...]\\\", which identifies one or more grid mapping variables, and with each grid mapping associates one or more coordinate_variables, i.e. coordinate variables or auxiliary coordinate variables.\\r\\n\\r\\nThis is illustrated by “Example 5.10. British National Grid”\\r\\n\\r\\n    float temp(z, y, x) ;\\r\\n      temp:grid_mapping = \\\"crsOSGB: x y crsWGS84: lat lon\\\" ;\\r\\n    int crsOSGB ;\\r\\n      crsOSGB:grid_mapping_name = \\\"transverse_mercator\\\";\\r\\n    int crsWGS84 ;\\r\\n      crsWGS84:grid_mapping_name = \\\"latitude_longitude\\\";\\r\\n\\r\\nSince [CF-1.8](http://cfconventions.org/Data/cf-conventions/cf-conventions-1.8/cf-conventions.html#use-of-the-crs-well-known-text-format) the extended format of the grid\\\\_mapping attribute may also provide\\r\\ncoordinate axis order, i.e.,\\r\\n\\r\\n    The order of the <coordinatesVariable> references within the grid_mapping attribute definition defines the order of elements within a derived coordinate value tuple. \\r\\n\\r\\nThis is illustrated by “Example 5.11. Latitude and longitude on the WGS 1984 datum + CRS WKT”\\r\\n\\r\\n    float data(latitude, longitude) ;\\r\\n      data:grid_mapping = \\\"crs: latitude, longitude\\\" ;\\r\\n    int crs ;\\r\\n      crs:grid_mapping_name = \\\"latitude_longitude\\\";\\r\\n\\r\\nUnfortunately, the package `ncmeta` does currently not recognize the crs of such files. Because of the exact matching used by function `ncmeta:::nc_grid_mapping_atts.data.frame()`, it currently cannot locate the corresponding crs of a grid mapping attribute in the extended format. It seems that the function could be enhanced to support the extended format if it would use partial matches or matches against the substring(s) before colon(s) of the grid mapping attribute. \\r\\n\\r\\nI recognize that additional design decisions would need to be taken for situations with multiple mappings, e.g., maybe pick the first and warn about the others?\\r\\n\\r\\n### A small reproducible example:\\r\\n\\r\\nFunction to create netCDFs illustrating simple and extended grid\\\\_mapping\\r\\n\\r\\n    create_ncdf_with_grid_mapping <- function(file, extended_grid_mapping = FALSE) {\\r\\n      nc <- RNetCDF::create.nc(file)\\r\\n\\r\\n      # Create x-y coordinates\\r\\n      RNetCDF::dim.def.nc(nc, \\\"lon\\\", 5)\\r\\n      RNetCDF::dim.def.nc(nc, \\\"lat\\\", 3)\\r\\n\\r\\n      # Create coordinate variables\\r\\n      RNetCDF::var.def.nc(nc, \\\"lon\\\", \\\"NC_DOUBLE\\\", \\\"lon\\\")\\r\\n      RNetCDF::var.def.nc(nc, \\\"lat\\\", \\\"NC_DOUBLE\\\", \\\"lat\\\")\\r\\n\\r\\n      # Create variable and add grid_mapping attribute\\r\\n      RNetCDF::var.def.nc(nc, \\\"var\\\", \\\"NC_DOUBLE\\\", c(\\\"lon\\\", \\\"lat\\\"))\\r\\n      tmp_gm <- if (extended_grid_mapping) \\\"crs: lat lon\\\" else \\\"crs\\\"\\r\\n      RNetCDF::att.put.nc(nc, \\\"var\\\", \\\"grid_mapping\\\", \\\"NC_CHAR\\\", tmp_gm)\\r\\n\\r\\n      # Create grid_mapping and add grid_mapping_name attribute\\r\\n      RNetCDF::var.def.nc(nc, \\\"crs\\\", \\\"NC_INT\\\", NA)\\r\\n      RNetCDF::att.put.nc(nc, \\\"crs\\\", \\\"grid_mapping_name\\\", \\\"NC_CHAR\\\", \\\"latitude_longitude\\\")\\r\\n\\r\\n      RNetCDF::close.nc(nc)\\r\\n\\r\\n      invisible(file)\\r\\n    }\\r\\n\\r\\nCreate example netCDFs\\r\\n\\r\\n    f1 <- tempfile(\\\"extended_grid_mapping_\\\", fileext = \\\".nc\\\")\\r\\n    f2 <- tempfile(\\\"simple_grid_mapping_\\\", fileext = \\\".nc\\\")\\r\\n\\r\\n    create_ncdf_with_grid_mapping(f1, extended_grid_mapping = TRUE)\\r\\n    create_ncdf_with_grid_mapping(f2)\\r\\n\\r\\nReading the extended grid\\\\_mapping produces a (non-fatal) error that results in no crs\\r\\n\\r\\n    x1 <- stars::read_ncdf(f1, var = \\\"var\\\")\\r\\n\\r\\n    ## Error in UseMethod(\\\"GPFN\\\") : \\r\\n    ##   no applicable method for 'GPFN' applied to an object of class \\\"list\\\"\\r\\n\\r\\n    sf::st_crs(x1)\\r\\n\\r\\n    ## Coordinate Reference System: NA\\r\\n\\r\\nReading the simple grid\\\\_mapping works as expected and results in the correct crs\\r\\n\\r\\n    x2 <- stars::read_ncdf(f2, var = \\\"var\\\")\\r\\n\\r\\n    ## Warning in getGeoDatum(gm): Didn't find a longitude of prime meridian for datum,\\r\\n    ## assuming 0.\\r\\n\\r\\n    ## Warning in getGeoDatum(gm): Didn't find a semi major axis for datum, assuming\\r\\n    ## WGS84 6378137.0 meters\\r\\n\\r\\n    ## Warning in getGeoDatum(gm): Didn't find an inverse flattening value, assuming\\r\\n    ## WGS84 298.257223563\\r\\n\\r\\n    sf::st_crs(x2)\\r\\n\\r\\n    ## Coordinate Reference System:\\r\\n    ##   User input: +proj=longlat +a=6378137 +f=0.00335281066474748 +pm=0 +no_defs \\r\\n    ##   wkt:\\r\\n    ## GEOGCRS[\\\"unknown\\\",\\r\\n    ##     DATUM[\\\"unknown\\\",\\r\\n    ##         ELLIPSOID[\\\"WGS 84\\\",6378137,298.257223563,\\r\\n    ##             LENGTHUNIT[\\\"metre\\\",1,\\r\\n    ##                 ID[\\\"EPSG\\\",9001]]]],\\r\\n    ##     PRIMEM[\\\"unknown\\\",0,\\r\\n    ##         ANGLEUNIT[\\\"degree\\\",0.0174532925199433,\\r\\n    ##             ID[\\\"EPSG\\\",9122]]],\\r\\n    ##     CS[ellipsoidal,2],\\r\\n    ##         AXIS[\\\"longitude\\\",east,\\r\\n    ##             ORDER[1],\\r\\n    ##             ANGLEUNIT[\\\"degree\\\",0.0174532925199433,\\r\\n    ##                 ID[\\\"EPSG\\\",9122]]],\\r\\n    ##         AXIS[\\\"latitude\\\",north,\\r\\n    ##             ORDER[2],\\r\\n    ##             ANGLEUNIT[\\\"degree\\\",0.0174532925199433,\\r\\n    ##                 ID[\\\"EPSG\\\",9122]]]]\\r\\n\\r\\nCleanup\\r\\n\\r\\n    unlink(c(f1, f2))\\r\\n\\r\\nI used\\r\\n\\r\\n    ncmeta\\\\_0.3.0, RNetCDF\\\\_2.4-2, sf\\\\_0.9-8, stars\\\\_0.4-3\\r\\n    Linking to GEOS 3.9.1, GDAL 3.2.0, PROJ 7.2.1\\r\\n\\r\\nMany thanks!\\r\\n\",\"closed_by\":null,\"reactions\":{\"url\":\"ghrepos/hypertidy/ncmeta/issues/41/reactions\",\"total_count\":0,\"+1\":0,\"-1\":0,\"laugh\":0,\"hooray\":0,\"confused\":0,\"heart\":0,\"rocket\":0,\"eyes\":0},\"timeline_url\":\"ghrepos/hypertidy/ncmeta/issues/41/timeline\",\"performed_via_github_app\":null,\"state_reason\":null,\"pinned_comment\":null},{\"url\":\"ghrepos/hypertidy/ncmeta/issues/40\",\"repository_url\":\"ghrepos/hypertidy/ncmeta\",\"labels_url\":\"ghrepos/hypertidy/ncmeta/issues/40/labels{/name}\",\"comments_url\":\"ghrepos/hypertidy/ncmeta/issues/40/comments\",\"events_url\":\"ghrepos/hypertidy/ncmeta/issues/40/events\",\"html_url\":\"https://github.com/hypertidy/ncmeta/pull/40\",\"id\":852265674,\"node_id\":\"MDExOlB1bGxSZXF1ZXN0NjEwNTQ3ODUz\",\"number\":40,\"title\":\"scale_factor_at_central_meridian for Transverse Mercator\",\"user\":{\"login\":\"floriandeboissieu\",\"id\":16676897,\"node_id\":\"MDQ6VXNlcjE2Njc2ODk3\",\"avatar_url\":\"https://avatars.githubusercontent.com/u/16676897?v=4\",\"gravatar_id\":\"\",\"url\":\"https://api.github.com/users/floriandeboissieu\",\"html_url\":\"https://github.com/floriandeboissieu\",\"followers_url\":\"https://api.github.com/users/floriandeboissieu/followers\",\"following_url\":\"https://api.github.com/users/floriandeboissieu/following{/other_user}\",\"gists_url\":\"https://api.github.com/users/floriandeboissieu/gists{/gist_id}\",\"starred_url\":\"https://api.github.com/users/floriandeboissieu/starred{/owner}{/repo}\",\"subscriptions_url\":\"https://api.github.com/users/floriandeboissieu/subscriptions\",\"organizations_url\":\"https://api.github.com/users/floriandeboissieu/orgs\",\"repos_url\":\"https://api.github.com/users/floriandeboissieu/repos\",\"events_url\":\"https://api.github.com/users/floriandeboissieu/events{/privacy}\",\"received_events_url\":\"https://api.github.com/users/floriandeboissieu/received_events\",\"type\":\"User\",\"user_view_type\":\"public\",\"site_admin\":false},\"labels\":[],\"state\":\"closed\",\"locked\":false,\"assignees\":[],\"milestone\":null,\"comments\":2,\"created_at\":\"2021-04-07T10:31:47Z\",\"updated_at\":\"2022-07-26T19:18:16Z\",\"closed_at\":\"2022-07-26T19:18:16Z\",\"assignee\":null,\"author_association\":\"CONTRIBUTOR\",\"issue_field_values\":[],\"type\":null,\"active_lock_reason\":null,\"draft\":false,\"pull_request\":{\"url\":\"ghrepos/hypertidy/ncmeta/pulls/40\",\"html_url\":\"https://github.com/hypertidy/ncmeta/pull/40\",\"diff_url\":\"https://github.com/hypertidy/ncmeta/pull/40.diff\",\"patch_url\":\"https://github.com/hypertidy/ncmeta/pull/40.patch\",\"merged_at\":\"2022-07-26T19:18:16Z\"},\"body\":\"This issue is of the same kind as PR #39 : refering to [CF conventions](http://cfconventions.org/cf-conventions/cf-conventions.html#appendix-grid-mappings) the scale factor variable name for transverse mercator is \\\"scale_factor_at_central_meridian\\\" instead of \\\"scale_factor_at_projection_origin\\\" for the others.\\r\\n\\r\\nThis PR fix it changing scaleFactor to scaleFactorCentMer and scaleFactorProjOrig depending on the case of Transverse Mercator or other.\\r\\nAlthough diff shows the whole file nc-gridmapping.R has changed, the only change is scaleFactor_gm to scaleFactorCentMer_gm and scaleFactorProjOrig_gm...\",\"closed_by\":{\"login\":\"mdsumner\",\"id\":4107631,\"node_id\":\"MDQ6VXNlcjQxMDc2MzE=\",\"avatar_url\":\"https://avatars.githubusercontent.com/u/4107631?v=4\",\"gravatar_id\":\"\",\"url\":\"https://api.github.com/users/mdsumner\",\"html_url\":\"https://github.com/mdsumner\",\"followers_url\":\"https://api.github.com/users/mdsumner/followers\",\"following_url\":\"https://api.github.com/users/mdsumner/following{/other_user}\",\"gists_url\":\"https://api.github.com/users/mdsumner/gists{/gist_id}\",\"starred_url\":\"https://api.github.com/users/mdsumner/starred{/owner}{/repo}\",\"subscriptions_url\":\"https://api.github.com/users/mdsumner/subscriptions\",\"organizations_url\":\"https://api.github.com/users/mdsumner/orgs\",\"repos_url\":\"https://api.github.com/users/mdsumner/repos\",\"events_url\":\"https://api.github.com/users/mdsumner/events{/privacy}\",\"received_events_url\":\"https://api.github.com/users/mdsumner/received_events\",\"type\":\"User\",\"user_view_type\":\"public\",\"site_admin\":false},\"reactions\":{\"url\":\"ghrepos/hypertidy/ncmeta/issues/40/reactions\",\"total_count\":0,\"+1\":0,\"-1\":0,\"laugh\":0,\"hooray\":0,\"confused\":0,\"heart\":0,\"rocket\":0,\"eyes\":0},\"timeline_url\":\"ghrepos/hypertidy/ncmeta/issues/40/timeline\",\"performed_via_github_app\":null,\"state_reason\":null},{\"url\":\"ghrepos/hypertidy/ncmeta/issues/39\",\"repository_url\":\"ghrepos/hypertidy/ncmeta\",\"labels_url\":\"ghrepos/hypertidy/ncmeta/issues/39/labels{/name}\",\"comments_url\":\"ghrepos/hypertidy/ncmeta/issues/39/comments\",\"events_url\":\"ghrepos/hypertidy/ncmeta/issues/39/events\",\"html_url\":\"https://github.com/hypertidy/ncmeta/pull/39\",\"id\":846486669,\"node_id\":\"MDExOlB1bGxSZXF1ZXN0NjA1NTc5MzI5\",\"number\":39,\"title\":\"longitude of central meridian \",\"user\":{\"login\":\"dblodgett-usgs\",\"id\":1492803,\"node_id\":\"MDQ6VXNlcjE0OTI4MDM=\",\"avatar_url\":\"https://avatars.githubusercontent.com/u/1492803?v=4\",\"gravatar_id\":\"\",\"url\":\"https://api.github.com/users/dblodgett-usgs\",\"html_url\":\"https://github.com/dblodgett-usgs\",\"followers_url\":\"https://api.github.com/users/dblodgett-usgs/followers\",\"following_url\":\"https://api.github.com/users/dblodgett-usgs/following{/other_user}\",\"gists_url\":\"https://api.github.com/users/dblodgett-usgs/gists{/gist_id}\",\"starred_url\":\"https://api.github.com/users/dblodgett-usgs/starred{/owner}{/repo}\",\"subscriptions_url\":\"https://api.github.com/users/dblodgett-usgs/subscriptions\",\"organizations_url\":\"https://api.github.com/users/dblodgett-usgs/orgs\",\"repos_url\":\"https://api.github.com/users/dblodgett-usgs/repos\",\"events_url\":\"https://api.github.com/users/dblodgett-usgs/events{/privacy}\",\"received_events_url\":\"https://api.github.com/users/dblodgett-usgs/received_events\",\"type\":\"User\",\"user_view_type\":\"public\",\"site_admin\":false},\"labels\":[],\"state\":\"closed\",\"locked\":false,\"assignees\":[],\"milestone\":null,\"comments\":0,\"created_at\":\"2021-03-31T11:36:49Z\",\"updated_at\":\"2021-04-01T03:17:33Z\",\"closed_at\":\"2021-04-01T03:17:33Z\",\"assignee\":null,\"author_association\":\"CONTRIBUTOR\",\"issue_field_values\":[],\"type\":null,\"active_lock_reason\":null,\"draft\":false,\"pull_request\":{\"url\":\"ghrepos/hypertidy/ncmeta/pulls/39\",\"html_url\":\"https://github.com/hypertidy/ncmeta/pull/39\",\"diff_url\":\"https://github.com/hypertidy/ncmeta/pull/39.diff\",\"patch_url\":\"https://github.com/hypertidy/ncmeta/pull/39.patch\",\"merged_at\":\"2021-04-01T03:17:33Z\"},\"body\":\"Related to https://github.com/r-spatial/stars/issues/393#issuecomment-810991898\",\"closed_by\":{\"login\":\"mdsumner\",\"id\":4107631,\"node_id\":\"MDQ6VXNlcjQxMDc2MzE=\",\"avatar_url\":\"https://avatars.githubusercontent.com/u/4107631?v=4\",\"gravatar_id\":\"\",\"url\":\"https://api.github.com/users/mdsumner\",\"html_url\":\"https://github.com/mdsumner\",\"followers_url\":\"https://api.github.com/users/mdsumner/followers\",\"following_url\":\"https://api.github.com/users/mdsumner/following{/other_user}\",\"gists_url\":\"https://api.github.com/users/mdsumner/gists{/gist_id}\",\"starred_url\":\"https://api.github.com/users/mdsumner/starred{/owner}{/repo}\",\"subscriptions_url\":\"https://api.github.com/users/mdsumner/subscriptions\",\"organizations_url\":\"https://api.github.com/users/mdsumner/orgs\",\"repos_url\":\"https://api.github.com/users/mdsumner/repos\",\"events_url\":\"https://api.github.com/users/mdsumner/events{/privacy}\",\"received_events_url\":\"https://api.github.com/users/mdsumner/received_events\",\"type\":\"User\",\"user_view_type\":\"public\",\"site_admin\":false},\"reactions\":{\"url\":\"g